function path(points,fill,stroke=null,lw=1){ctx.beginPath();points.forEach((p,i)=>i?ctx.lineTo(p[0],p[1]):ctx.moveTo(p[0],p[1]));ctx.closePath();if(fill){ctx.fillStyle=fill;ctx.fill()}if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=lw;ctx.stroke()}}
function circle(x,y,r,fill,stroke=null,lw=1){ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);ctx.fillStyle=fill;ctx.fill();if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=lw;ctx.stroke()}}
function palm(x,y,s){ctx.save();ctx.translate(x,y);ctx.scale(s,s);ctx.strokeStyle='#654c39';ctx.lineWidth=7;ctx.lineCap='round';ctx.beginPath();ctx.moveTo(0,0);ctx.quadraticCurveTo(-4,-38,3,-90);ctx.stroke();ctx.fillStyle='#267c69';for(let i=0;i<8;i++){let a=-Math.PI*.95+i*Math.PI*1.9/7;ctx.save();ctx.translate(3,-90);ctx.rotate(a);ctx.beginPath();ctx.moveTo(0,0);ctx.quadraticCurveTo(22,-12,51,2);ctx.quadraticCurveTo(25,2,0,0);ctx.fill();ctx.restore()}circle(3,-90,5,'#805d39');ctx.restore()}
function cloud(x,y,s,a){ctx.save();ctx.globalAlpha=a;ctx.fillStyle='#fff9e9';ctx.beginPath();ctx.ellipse(x,y,42*s,12*s,0,0,Math.PI*2);ctx.ellipse(x-17*s,y-5*s,18*s,14*s,0,0,Math.PI*2);ctx.ellipse(x+4*s,y-10*s,21*s,18*s,0,0,Math.PI*2);ctx.ellipse(x+25*s,y-4*s,19*s,13*s,0,0,Math.PI*2);ctx.fill();ctx.restore()}
function drawSky(t){let sky=ctx.createLinearGradient(0,0,0,H*.68);if(weather===3){sky.addColorStop(0,'#efaa75');sky.addColorStop(.52,'#f5c69a');sky.addColorStop(1,'#b3d4ca')}else if(weather===2){sky.addColorStop(0,'#a4b7c1');sky.addColorStop(.65,'#c7d4d0');sky.addColorStop(1,'#b2d8d1')}else{sky.addColorStop(0,'#67b8d0');sky.addColorStop(.53,'#a7d7d2');sky.addColorStop(1,'#e1e3be')}ctx.fillStyle=sky;ctx.fillRect(0,0,W,H*.68);let sunX=W*.77,sunY=H*.16;circle(sunX,sunY,weather===3?37:30,weather===2?'#e7e8d4':'#ffe6a0');let glow=ctx.createRadialGradient(sunX,sunY,5,sunX,sunY,weather===3?140:115);glow.addColorStop(0,'#ffe7b577');glow.addColorStop(1,'#ffe7b500');ctx.fillStyle=glow;ctx.fillRect(sunX-150,sunY-150,300,300);cloud(W*.18+Math.sin(t*.0001)*20,H*.16,.9,.72);cloud(W*.48,H*.11,.62,.48);cloud(W*.89,H*.28,.68,.62);
// distant mountain ridges
let hy=H*.365;path([[0,hy+40],[W*.07,hy-5],[W*.15,hy+14],[W*.24,hy-46],[W*.32,hy+18],[W*.43,hy-22],[W*.55,hy+11],[W*.66,hy-54],[W*.74,hy+12],[W*.85,hy-18],[W,hy+24],[W,H*.58],[0,H*.58]],'#729a91');path([[0,hy+53],[W*.13,hy+18],[W*.26,hy+34],[W*.40,hy-3],[W*.54,hy+37],[W*.71,hy+4],[W*.83,hy+28],[W,hy+2],[W,H*.58],[0,H*.58]],'#8daf9e');
// distant city blocks
for(let i=0;i<18;i++){let x=i*W/15-20,w=18+hash(i+8)*33,h=30+hash(i+2)*85,y=hy+42-h;ctx.fillStyle=['#a9b5a8','#d8c9a5','#829b94','#c8b697'][i%4];ctx.fillRect(x,y,w,h);ctx.fillStyle='#e7d99d88';for(let j=0;j<3;j++)ctx.fillRect(x+5+j*8,y+9,4,6)}
// ocean band and glints
let oy=H*.49;ctx.fillStyle=weather===2?'#668e99':'#63bac1';ctx.fillRect(0,oy,W,H*.12);ctx.fillStyle='#d5eee0';for(let i=0;i<24;i++){let x=(i*113+elapsed*11)%W,y=oy+10+hash(i+45)*H*.08;ctx.globalAlpha=.16+hash(i)*.16;ctx.fillRect(x,y,14+hash(i+3)*30,1.3)}ctx.globalAlpha=1;
// distant pier / ferris wheel motif
let px=W*.78,py=oy+13,scale=Math.max(.56,Math.min(1,W/1000));ctx.strokeStyle='#d6d5bd';ctx.lineWidth=2*scale;ctx.beginPath();ctx.moveTo(px-55*scale,py+28*scale);ctx.lineTo(px+75*scale,py+28*scale);ctx.stroke();for(let i=0;i<5;i++){ctx.beginPath();ctx.moveTo(px-40*scale+i*30*scale,py+28*scale);ctx.lineTo(px-40*scale+i*30*scale,py+45*scale);ctx.stroke()}let fr=24*scale;circle(px,py,fr,'#e9d8b055','#f6e5c4',2*scale);for(let i=0;i<8;i++){let a=i*Math.PI/4;ctx.beginPath();ctx.moveTo(px,py);ctx.lineTo(px+Math.cos(a)*fr,py+Math.sin(a)*fr);ctx.stroke();circle(px+Math.cos(a)*fr,py+Math.sin(a)*fr,2.7*scale,'#ffd77c')}circle(px,py,3*scale,'#fff0c4');
// striped beach area
ctx.fillStyle='#d8c69a';ctx.fillRect(0,oy+H*.09,W,H*.07);for(let i=0;i<7;i++){let x=(i*W/6+progress*.05)%W;ctx.fillStyle=i%2?'#fff0ce':'#e98069';ctx.beginPath();ctx.moveTo(x,oy+H*.06);ctx.lineTo(x-15,oy+H*.1);ctx.lineTo(x+18,oy+H*.1);ctx.closePath();ctx.fill();ctx.fillStyle='#86664c';ctx.fillRect(x,oy+H*.1,2,10)}
}
function project(z,x){let k=1-z;let horizon=H*.49;let y=horizon+k*(H*.55);let half= W*(.08+k*.39);return {x:W*.5+x*half,y,scale:.18+k*1.7,half}}
function drawBalloon(x,y,s,color){ctx.save();ctx.translate(x,y);ctx.scale(s,s);ctx.strokeStyle='#e6d9ba';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(0,11);ctx.lineTo(-2,35);ctx.stroke();ctx.fillStyle=color;ctx.beginPath();ctx.moveTo(0,-16);ctx.bezierCurveTo(25,-15,22,10,3,14);ctx.lineTo(-3,14);ctx.bezierCurveTo(-22,8,-22,-15,0,-16);ctx.fill();ctx.fillStyle='#fff8';ctx.beginPath();ctx.ellipse(-7,-6,4,8,-.4,0,Math.PI*2);ctx.fill();ctx.fillStyle='#8c6954';ctx.fillRect(-4,13,9,7);ctx.restore()}
function drawScenery(t){let near=.03;for(let i=0;i<8;i++){let z=((i/8-(progress*.0008)%1)+1)%1;let p=project(z,0);let scale=p.scale;let xL=p.x-p.half-3*scale,xR=p.x+p.half+3*scale;
// sidewalks / blocks
ctx.fillStyle='#d9c9a8';ctx.fillRect(xL,p.y-4*scale,Math.max(1,p.half*.34),H-p.y+10);ctx.fillRect(xR,p.y-4*scale,Math.max(1,p.half*.34),H-p.y+10);ctx.fillStyle='#b8aa91';ctx.fillRect(xL,p.y-4*scale,Math.max(1,p.half*.34),3*scale);ctx.fillRect(xR,p.y-4*scale,Math.max(1,p.half*.34),3*scale);
// repeating palm rows
for(let side of [-1,1]){let xx=p.x+side*(p.half+42*scale);let yy=p.y+13*scale;if(xx>-80&&xx<W+80)palm(xx,yy,scale*.72);let bx=p.x+side*(p.half+105*scale);if(z>.18&&bx>-140&&bx<W+140){let bw=(55+hash(i+side*2)*28)*scale,bh=(90+hash(i*4+side)*80)*scale;let by=p.y-bh+8*scale;let col=['#c89e7a','#b8a78d','#718e89','#e3c9a2','#9a9d8b'][(i+(side>0?1:0))%5];ctx.fillStyle=col;ctx.fillRect(bx-bw/2,by,bw,bh);ctx.fillStyle='#f0d7ae';ctx.fillRect(bx-bw/2,by,bw,5*scale);for(let wx=0;wx<3;wx++)for(let wy=0;wy<Math.min(5,bh/(14*scale));wy++){ctx.fillStyle=weather===3?'#ffc975':'#f1dfab';ctx.globalAlpha=.75;ctx.fillRect(bx-bw/2+7*scale+wx*12*scale,by+12*scale+wy*13*scale,5*scale,6*scale)}ctx.globalAlpha=1;ctx.fillStyle='#6b5140';ctx.fillRect(bx-11*scale,by+bh-27*scale,22*scale,27*scale);if(i===3&&side===1){ctx.fillStyle='#f1d38e';ctx.font=`${11*scale}px sans-serif`;ctx.fillText('CAFÉ',bx-bw/3,by+bh*.63)}}}
}
// a couple of distant festival balloons
for(let j=0;j<3;j++){let x=W*(.25+j*.24)+Math.sin(t*.0007+j)*16,y=H*(.31+hash(j)*.04);drawBalloon(x,y,.6+hash(j+10)*.35,['#ef8d76','#ffce72','#94d7c2'][j])}
}

function roadY(y){let q=clamp((y-H*.49)/(H*.53),0,1);return W*(.115+q*.36)}
function drawRoad(t){let hy=H*.49;path([[W*.5-W*.12,hy],[W*.5+W*.12,hy],[W*.5+roadY(H),H],[W*.5-roadY(H),H]],'#525c5d'); // asphalt gradient
let g=ctx.createLinearGradient(0,hy,0,H);g.addColorStop(0,'#616d6b');g.addColorStop(1,'#384449');path([[W*.5-W*.12,hy],[W*.5+W*.12,hy],[W*.5+roadY(H),H],[W*.5-roadY(H),H]],g);
// road edge paint
for(let side of [-1,1]){ctx.strokeStyle='#eee3c5aa';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(W*.5+side*W*.115,hy);ctx.lineTo(W*.5+side*roadY(H)*.94,H);ctx.stroke()}
// dashed center line
let offset=(progress*.0012)%1;for(let i=0;i<13;i++){let z=((i/13+offset)%1);let y=hy+z*(H-hy);let half=roadY(y);let len=2+z*28;ctx.fillStyle='#efe5c2';ctx.globalAlpha=.45+z*.45;ctx.fillRect(W*.5-1.6-z, y-len/2,3+z*2,len)}ctx.globalAlpha=1;
// lane separators subtle
for(let side of [-1,1]){ctx.strokeStyle='#ffffff25';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(W*.5+side*W*.04,hy);ctx.lineTo(W*.5+side*roadY(H)*.34,H);ctx.stroke()}
// shadows and road texture flecks
for(let i=0;i<34;i++){let z=(hash(i+3)*.95+.03);let y=hy+z*(H-hy);let x=W*.5+(hash(i+33)*2-1)*roadY(y)*.88;ctx.fillStyle='#d2c8a644';ctx.fillRect(x,y,1+z*4,1+z)}
}
function drawParcel(it){let p=project(it.z,it.x*.62);let s=p.scale;ctx.save();ctx.translate(p.x,p.y-4*s);ctx.scale(s,s);ctx.shadowColor='#172c36';ctx.shadowBlur=10;ctx.shadowOffsetY=5;ctx.fillStyle='#d59c62';ctx.beginPath();ctx.roundRect(-12,-19,24,20,3);ctx.fill();ctx.shadowColor='transparent';ctx.fillStyle='#f0cb8c';ctx.fillRect(-3,-19,6,20);ctx.fillStyle='#f3dfb7';ctx.fillRect(-12,-12,24,3);ctx.fillStyle='#526c66';ctx.beginPath();ctx.moveTo(-12,1);ctx.lineTo(0,-5);ctx.lineTo(12,1);ctx.fill();ctx.restore();
}
function drawPedestrian(x,y,s,color,phase){ctx.save();ctx.translate(x,y);ctx.scale(s,s);ctx.fillStyle='#162e3a30';ctx.beginPath();ctx.ellipse(0,1,9,3,0,0,7);ctx.fill();ctx.strokeStyle=color;ctx.lineWidth=4;ctx.lineCap='round';let sw=Math.sin(elapsed*4+phase)*3;ctx.beginPath();ctx.moveTo(-2,-11);ctx.lineTo(-4+sw,0);ctx.moveTo(2,-11);ctx.lineTo(4-sw,0);ctx.stroke();ctx.fillStyle=color;ctx.beginPath();ctx.roundRect(-6,-28,12,17,4);ctx.fill();circle(0,-33,5,'#c98f6c');ctx.fillStyle='#342e2c';ctx.beginPath();ctx.arc(0,-35,5,Math.PI,0);ctx.fill();ctx.restore()}
function drawStreetLife(){for(let i=0;i<5;i++){let z=(.18+i*.17-(progress*.00045)%1);z=(z%1+1)%1;let p=project(z,0);let side=i%2?1:-1;let px=p.x+side*(p.half+22*p.scale);if(px>-50&&px<W+50)drawPedestrian(px,p.y+9*p.scale,p.scale*.52,['#db785d','#526c7c','#e3b857','#8f7764'][i%4],i)}
}
function drawCourier(t){let x=W*.5+lane*roadY(H)*.37+Math.sin((targetLane-lane)*4)*4;let y=H*.88;let sc=Math.min(1.05,Math.max(.67,H/800));ctx.save();ctx.translate(x,y);ctx.scale(sc,sc);let bob=Math.sin(t*.009)*2;ctx.translate(0,bob);
// ground shadow
ctx.fillStyle='#12232d77';ctx.beginPath();ctx.ellipse(0,15,67,13,0,0,Math.PI*2);ctx.fill();
// rear wheel
ctx.strokeStyle='#182a32';ctx.lineWidth=7;circle(0,-3,31,'#263941','#16272e',4);circle(0,-3,24,'#758783','#263941',1.5);circle(0,-3,4,'#e1bd7b');for(let i=0;i<8;i++){let a=i*Math.PI/4;ctx.strokeStyle='#c2cec0aa';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(0,-3);ctx.lineTo(Math.cos(a)*23,Math.sin(a)*23-3);ctx.stroke()}
// vehicle frame / body
ctx.strokeStyle=ride===2?'#e7b45f':'#e0b56d';ctx.lineWidth=5;ctx.lineCap='round';ctx.beginPath();ctx.moveTo(0,-5);ctx.lineTo(-26,-43);ctx.lineTo(23,-42);ctx.lineTo(0,-5);ctx.lineTo(14,-43);ctx.stroke();ctx.fillStyle=ride===1?'#e8a65d':'#435e5d';ctx.beginPath();ctx.roundRect(-22,-55,44,21,7);ctx.fill();ctx.fillStyle='#ffcf73';ctx.beginPath();ctx.roundRect(-18,-52,36,13,5);ctx.fill();
// basket with parcels
ctx.fillStyle='#d5a56d';ctx.beginPath();ctx.roundRect(-27,-82,54,30,7);ctx.fill();ctx.fillStyle='#f0d7a4';ctx.beginPath();ctx.roundRect(-21,-88,42,16,5);ctx.fill();ctx.fillStyle='#aa754f';ctx.fillRect(-18,-77,36,3);ctx.fillStyle='#f5dfb6';ctx.fillRect(-4,-88,8,36);
// arms and torso (back facing)
ctx.strokeStyle=outfit===1?'#526c85':'#e8b57d';ctx.lineWidth=11;ctx.beginPath();ctx.moveTo(-9,-113);ctx.lineTo(-24,-88);ctx.lineTo(-17,-67);ctx.moveTo(9,-113);ctx.lineTo(24,-88);ctx.lineTo(17,-67);ctx.stroke();ctx.fillStyle=outfit===1?'#708da2':outfit===2?'#344d62':'#e9784e';ctx.beginPath();ctx.roundRect(-17,-132,34,41,11);ctx.fill();ctx.fillStyle='#f2cb72';ctx.fillRect(-13,-116,26,4);ctx.fillStyle='#f6d594';ctx.beginPath();ctx.arc(0,-146,16,0,Math.PI*2);ctx.fill();ctx.fillStyle=outfit===2?'#304858':'#e47b4e';ctx.beginPath();ctx.ellipse(0,-152,20,7,0,Math.PI,Math.PI*2);ctx.fill();ctx.fillRect(-17,-153,34,4);
// legs and shoes
ctx.strokeStyle='#3c5361';ctx.lineWidth=9;ctx.beginPath();ctx.moveTo(-8,-92);ctx.lineTo(-15,-53);ctx.moveTo(8,-92);ctx.lineTo(15,-53);ctx.stroke();ctx.strokeStyle='#e7e0cc';ctx.lineWidth=7;ctx.beginPath();ctx.moveTo(-16,-50);ctx.lineTo(-28,-46);ctx.moveTo(16,-50);ctx.lineTo(28,-46);ctx.stroke();
// handlebar & bell
ctx.strokeStyle='#263a42';ctx.lineWidth=5;ctx.beginPath();ctx.moveTo(-25,-65);ctx.lineTo(-27,-85);ctx.lineTo(-39,-85);ctx.moveTo(27,-85);ctx.lineTo(39,-85);ctx.stroke();if(bell){circle(0,-172,10,'#ffe17b');ctx.strokeStyle='#fff3c8';ctx.lineWidth=2;ctx.beginPath();ctx.arc(0,-172,17,-.8,.8);ctx.stroke()}
// vehicle variant skateboard hint
if(ride===2){ctx.fillStyle='#dc9259';ctx.beginPath();ctx.roundRect(-32,-12,64,7,4);ctx.fill();circle(-22,-3,4,'#27383f');circle(22,-3,4,'#27383f')}
ctx.restore()}
function drawRain(t){if(weather!==2)return;ctx.strokeStyle='#d9f4f3aa';ctx.lineWidth=1;for(let i=0;i<85;i++){let x=(hash(i+4)*W+t*.18*(i%4+1))%W,y=(hash(i+55)*H+t*.45*(i%5+1))%H;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x-5,y+15);ctx.stroke()}}
function draw(t){ctx.clearRect(0,0,W,H);drawSky(t);drawScenery(t);drawRoad(t);drawStreetLife();items.forEach(it=>{if(!it.got)drawParcel(it)});drawCourier(t);drawRain(t);if(shake>0)shake--;
// location progresses through coastal districts
let loc=progress<850?'Венис-Бич':progress<1800?'Санта-Моника':progress<2750?'Порт Лос-Анджелеса':progress<3700?'Даунтаун':'Парк аттракционов';document.getElementById('locationLabel').textContent=loc;
}
setHUD();draw(0);
</script></body></html>

